import type { Input, Options, Run, Side } from '../../../../scripts/benchmarkNativeAnalysis/contract.ts'
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { lstat, mkdir, readdir, readFile, realpath, rename, writeFile } from 'node:fs/promises'
import { getCompileCacheDir } from 'node:module'
import process from 'node:process'
import path from 'node:path'
import { collectRun } from './collect.mts'

interface Task {
  options: Omit<Options, 'signal'>
  input: Input
  stage: Run['kind']
  native: Side
  variant: string
  pair: number
  batch: Run['batch']
  resultFile: string
  temporaryDirectory: string
  observationFile: string
  cachePolicy: { contract: string, rolldownCaches: { names: string[], policy: string }, inputCaches: { names: string[], location: string, policy: string } }
}

interface CacheManifest {
  files: Record<string, { sha256: string, bytes: number, mode: number }>
  directories: string[]
  digest: string
}

interface OwnedCacheObservation {
  name: string
  source: string
  beforeAbsent: boolean | null
  after: { status: 'not-observed' | 'absent' | 'present', isDirectory: boolean | null, isSymbolicLink: boolean | null, entryCount: number | null }
  archive: { status: 'not-started' | 'absent' | 'archived' | 'failed', directory?: string, error?: string }
  sourceAbsentAfterArchive: boolean | null
  beforeArchiveManifest: CacheManifest | null
  archivedManifest: CacheManifest | null
}

const rolldownCacheNames = ['.rolldown-require', '.rolldown-require-cache'] as const
const inputCacheNames = ['.vite', '.vite-temp'] as const
const archivePolicy = 'absent-before-prepare; first-repeat-share; archive-owned-directory-after-collectRun'
const sha256 = (value: Uint8Array | string) => createHash('sha256').update(value).digest('hex')
const absentOrStat = (file: string) => lstat(file).catch((error: NodeJS.ErrnoException) => { if (error.code === 'ENOENT') return null; throw error })

// 每侧使用新进程，避免同一路径更换依赖链接后沿用 Node 的 realpath/解析缓存。
assert(process.argv[2] && process.argv.length === 3, 'Expected one private collector task')
const task = JSON.parse(await readFile(process.argv[2], 'utf8')) as Task
assert(['primary', 'confirmation'].includes(task.batch) && ['off', 'on'].includes(task.native))
assert(Number.isInteger(task.pair) && task.pair >= 0 && /^[a-z\d-]+$/i.test(task.variant))
assert.equal(task.cachePolicy.contract, 'isolated-collect-cache-policy-v2')
assert.deepEqual(task.cachePolicy.rolldownCaches, { names: [...rolldownCacheNames], policy: archivePolicy })
assert.deepEqual(task.cachePolicy.inputCaches, { names: [...inputCacheNames], location: 'input.dependencies/node_modules', policy: archivePolicy })
assert(path.isAbsolute(task.temporaryDirectory))
assert(task.temporaryDirectory.startsWith(`${path.join(task.options.output, 'temporary')}${path.sep}`))
for (const key of ['TMPDIR', 'TMP', 'TEMP']) assert.equal(process.env[key], task.temporaryDirectory, `Wrong managed ${key}`)
if (task.options.mode === 'full') assert(task.native === 'off' && task.options.buildPairs === 40 && task.options.hmrPairs === 40)
assert.equal(process.env.NODE_COMPILE_CACHE, undefined, 'Worker inherited automatic compile cache')
assert.equal(process.env.NODE_DISABLE_COMPILE_CACHE, undefined, 'Worker inherited compile-cache disable switch')
assert.equal(process.env.TSX_DISABLE_CACHE, '1', 'Worker transpile cache must be disabled before startup')
process.env.NODE_OPTIONS = ''
process.env.NODE_PATH = ''
process.env.NATIVE_BENCHMARK_SOURCE_ROOTS = '1'
delete process.env.NODE_COMPILE_CACHE
delete process.env.NODE_DISABLE_COMPILE_CACHE
const controller = new AbortController()
const stop = () => controller.abort()
process.once('SIGINT', stop)
process.once('SIGTERM', stop)
const cache = path.join(task.options.root, 'packages/weapp-vite/.cache')
const runtimeModules = path.join(task.options.root, 'node_modules')
const inputModules = path.join(task.options.root, task.input.dependencies, 'node_modules')
const createCacheObservations = (names: readonly string[], modules: string): OwnedCacheObservation[] => names.map(name => ({
  name, source: path.join(modules, name), beforeAbsent: null,
  after: { status: 'not-observed', isDirectory: null, isSymbolicLink: null, entryCount: null },
  archive: { status: 'not-started' }, sourceAbsentAfterArchive: null, beforeArchiveManifest: null, archivedManifest: null,
}))
const rolldownCaches = createCacheObservations(rolldownCacheNames, runtimeModules)
const inputCaches = createCacheObservations(inputCacheNames, inputModules)
const cacheGroups = [
  { modules: runtimeModules, archiveGroup: 'rolldown-cache', items: rolldownCaches },
  { modules: inputModules, archiveGroup: 'input-cache', items: inputCaches },
] as const
const observation: {
  contract: string, cachePolicy: Task['cachePolicy'], variant: string, batch: Run['batch'], pair: number, input: string, kind: Run['kind'],
  temporaryDirectory: string, beforePrepare: unknown, afterCollect: unknown, cliCompileCacheApiStatus: string,
  npmArchive: { status: string, directory?: string, error?: string }, error?: string,
  rolldownCaches: OwnedCacheObservation[], inputCaches: OwnedCacheObservation[],
} = {
  contract: 'isolated-cache-observation-v1', cachePolicy: task.cachePolicy, variant: task.variant, batch: task.batch, pair: task.pair,
  input: task.input.id, kind: task.stage, temporaryDirectory: task.temporaryDirectory,
  beforePrepare: null, afterCollect: null, cliCompileCacheApiStatus: 'not-observed', npmArchive: { status: 'not-started' },
  rolldownCaches, inputCaches,
}

/** 仅允许在当前隔离运行时的真实模块目录下归档本轮新增缓存。 */
async function assertOwnedModules(directory: string) {
  const root = await realpath(task.options.root)
  assert.equal(root, path.resolve(task.options.root), 'Runtime root must not redirect')
  assert(path.resolve(directory).startsWith(`${root}${path.sep}`), 'Cache owner must remain inside runtime root')
  const modules = await lstat(directory)
  assert(modules.isDirectory() && !modules.isSymbolicLink(), 'Runtime node_modules must be a real directory')
  assert.equal(await realpath(directory), path.resolve(directory), 'Runtime node_modules must not redirect')
}

/** 对归档前后的普通文件、子目录、字节数和权限生成稳定摘要。 */
async function cacheManifest(root: string): Promise<CacheManifest> {
  const files: CacheManifest['files'] = {}
  const directories: string[] = []
  async function walk(directory: string) {
    for (const entry of await readdir(directory, { withFileTypes: true })) {
      const filename = path.join(directory, entry.name)
      const relative = path.relative(root, filename).split(path.sep).join('/')
      const stat = await lstat(filename)
      assert(!stat.isSymbolicLink(), `Cache manifest refuses nested symlink: ${relative}`)
      if (stat.isDirectory()) { directories.push(relative); await walk(filename) }
      else {
        assert(stat.isFile(), `Cache manifest refuses non-file: ${relative}`)
        const bytes = await readFile(filename)
        assert.equal(bytes.byteLength, stat.size, `Cache file changed during manifest: ${relative}`)
        files[relative] = { sha256: sha256(bytes), bytes: stat.size, mode: stat.mode }
      }
    }
  }
  await walk(root)
  const sortedFiles = Object.fromEntries(Object.keys(files).sort().map(file => [file, files[file]!]))
  const sortedDirectories = directories.sort()
  return { files: sortedFiles, directories: sortedDirectories, digest: sha256(JSON.stringify({ files: sortedFiles, directories: sortedDirectories })) }
}

/** 保留临时目录和持久缓存的独立证据，不归档已有资源或符号链接。 */
async function archiveOwnedCache(item: OwnedCacheObservation, modules: string, archiveGroup: string) {
  assert.equal(item.beforeAbsent, true, `Cache was not absent before prepare: ${item.name}`)
  await assertOwnedModules(modules)
  assert.equal(item.source, path.join(modules, item.name), 'Cache source differs from owned module directory')
  const stat = await absentOrStat(item.source)
  if (!stat) {
    item.after = { status: 'absent', isDirectory: false, isSymbolicLink: false, entryCount: 0 }
    item.archive = { status: 'absent' }
    item.sourceAbsentAfterArchive = true
    return
  }
  item.after = { status: 'present', isDirectory: stat.isDirectory(), isSymbolicLink: stat.isSymbolicLink(), entryCount: null }
  assert(stat.isDirectory() && !stat.isSymbolicLink(), `Refusing to archive non-directory or symlink cache: ${item.name}`)
  item.after.entryCount = (await readdir(item.source)).length
  item.beforeArchiveManifest = await cacheManifest(item.source)
  const directory = path.join(task.options.output, archiveGroup, task.batch, String(task.pair), task.stage, task.input.id, task.variant, item.name)
  await mkdir(path.dirname(directory), { recursive: true })
  assert.equal(await absentOrStat(directory), null, `Preserve existing cache archive: ${item.name}`)
  const current = await lstat(item.source)
  assert(current.isDirectory() && !current.isSymbolicLink() && current.dev === stat.dev && current.ino === stat.ino, `Cache changed before archive: ${item.name}`)
  await rename(item.source, directory)
  item.archive = { status: 'archived', directory }
  const archived = await lstat(directory)
  assert(archived.isDirectory() && !archived.isSymbolicLink() && archived.dev === stat.dev && archived.ino === stat.ino, `Archived cache identity changed: ${item.name}`)
  item.archivedManifest = await cacheManifest(directory)
  assert.deepEqual(item.archivedManifest, item.beforeArchiveManifest, `Cache manifest changed after archive: ${item.name}`)
  item.sourceAbsentAfterArchive = await absentOrStat(item.source) === null
  assert(item.sourceAbsentAfterArchive, `Cache source remained after archive: ${item.name}`)
}

let started = false
try {
  const priorCache = await absentOrStat(cache)
  for (const group of cacheGroups) {
    await assertOwnedModules(group.modules)
    for (const item of group.items) item.beforeAbsent = await absentOrStat(item.source) === null
  }
  const temporaryEntries = await readdir(task.temporaryDirectory)
  observation.beforePrepare = {
    temporaryDirectoryEmpty: temporaryEntries.length === 0, npmCacheAbsent: priorCache === null,
    workerCompileCacheDirectory: getCompileCacheDir() ?? null,
    environment: { TMPDIR: process.env.TMPDIR, TMP: process.env.TMP, TEMP: process.env.TEMP, NODE_COMPILE_CACHE: process.env.NODE_COMPILE_CACHE ?? null, NODE_DISABLE_COMPILE_CACHE: process.env.NODE_DISABLE_COMPILE_CACHE ?? null, TSX_DISABLE_CACHE: process.env.TSX_DISABLE_CACHE },
  }
  assert.equal(temporaryEntries.length, 0, 'Initial managed temporary directory must be empty')
  assert.equal(priorCache, null, 'Initial npm cache must be absent; preserve unexpected prior state')
  for (const group of cacheGroups) for (const item of group.items) assert.equal(item.beforeAbsent, true, `Initial ${item.name} must be absent; preserve unexpected prior state`)
  assert.equal(getCompileCacheDir(), undefined, 'Collector worker must not activate compile cache')
  assert(!controller.signal.aborted, 'Collector interrupted before startup')
  started = true
  const result = await collectRun({ ...task.options, signal: controller.signal }, task.input, task.stage, task.native, task.pair, task.batch)
  await writeFile(task.resultFile, JSON.stringify(result), { flag: 'wx' })
}
catch (error) { observation.error = String(error); throw error }
finally {
  try {
    if (started) {
      const cleanupErrors: unknown[] = []
      // 首次构建空缓存，同侧首次与重复共享缓存；结束后移到本次证据目录。
      try {
        const retained = path.join(task.options.output, 'npm-cache', task.batch, String(task.pair), task.stage, task.input.id)
        await mkdir(retained, { recursive: true })
        const directory = path.join(retained, task.variant)
        try { await rename(cache, directory); observation.npmArchive = { status: 'archived', directory } }
        catch (error) {
          if ((error as NodeJS.ErrnoException).code === 'ENOENT') observation.npmArchive = { status: 'absent' }
          else { observation.npmArchive = { status: 'failed', directory, error: String(error) }; throw error }
        }
      }
      catch (error) {
        if (observation.npmArchive.status !== 'failed') observation.npmArchive = { status: 'failed', error: String(error) }
        cleanupErrors.push(error)
      }
      for (const group of cacheGroups) for (const item of group.items) {
        try { await archiveOwnedCache(item, group.modules, group.archiveGroup) }
        catch (error) {
          item.archive = { ...item.archive, status: 'failed', error: String(error) }
          cleanupErrors.push(error)
        }
      }
      if (cleanupErrors.length) {
        const error = new AggregateError(cleanupErrors, 'Owned cache archival failed')
        observation.error = [observation.error, String(error)].filter(Boolean).join('; ')
        throw error
      }
    }
  }
  finally {
    try {
      observation.afterCollect = { temporaryDirectoryEntryCount: (await readdir(task.temporaryDirectory)).length, workerCompileCacheDirectory: getCompileCacheDir() ?? null }
      await writeFile(task.observationFile, `${JSON.stringify(observation, null, 2)}\n`, { flag: 'wx' })
    }
    finally {
      process.off('SIGINT', stop)
      process.off('SIGTERM', stop)
    }
  }
}

