import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'
import { SCENARIOS, SOURCE_SCOPE } from './contract.mjs'

const epoch = (trace, event) => trace.clock.timeOrigin + event.atMs
const samePhase = (a, b) => ['scenario', 'index', 'phase'].every(key => a[key] === b[key])

/** 快照只作进程归因；CPU/ELU 与 wall 不能作为可加总的互斥阶段。 */
function interval(trace, begin, end) {
  assert(end.sequence > begin.sequence)
  const delta = key => Object.fromEntries(Object.keys(begin.resources[key]).map(field => [field, end.resources[key][field] - begin.resources[key][field]]))
  return {
    beginSequence: begin.sequence, endSequence: end.sequence,
    beginEpochMs: epoch(trace, begin), endEpochMs: epoch(trace, end), elapsedMs: end.atMs - begin.atMs,
    cpuDeltaMicros: delta('cpu'),
    eluDeltaMs: { active: end.resources.elu.active - begin.resources.elu.active, idle: end.resources.elu.idle - begin.resources.elu.idle },
    memoryBefore: begin.resources.memory, memoryAfter: end.resources.memory,
  }
}

function overlappingGc(trace, beginEpochMs, endEpochMs) {
  return trace.records.filter(event => event.event === 'gc').flatMap((event) => {
    const start = trace.clock.timeOrigin + event.gc.startTime
    const end = start + event.gc.duration
    if (end < beginEpochMs || start > endEpochMs) return []
    return [{ sequence: event.sequence, ...event.gc, startEpochMs: start, endEpochMs: end, deliveryEpochMs: epoch(trace, event), delivery: event.delivery, deliveryResources: event.resources }]
  })
}

/** 检查全部 Native 阶段与轮询，不挑最有利周期或丢弃读错误。 */
export function analyzeRun(run) {
  assert.equal(run.input, 'weapp-vite-template')
  assert.equal(run.trace.length, 2)
  const driver = run.trace.find(trace => trace.role === 'driver')
  const cli = run.trace.find(trace => trace.role === 'cli')
  assert(driver && cli)
  for (const trace of run.trace) {
    assert.equal(trace.contract, 'private-hmr-native-restore-observer-v2')
    assert.deepEqual(trace.errors, [])
    assert.equal(trace.dropped, 0)
    assert.equal(trace.code, trace.role === 'cli' ? 143 : 0)
    trace.records.forEach((event, i) => {
      assert.equal(event.sequence, i + 1)
      assert(Number.isFinite(event.atMs))
      if (i) assert(event.atMs >= trace.records[i - 1].atMs)
      for (const key of ['cpu', 'elu', 'memory']) assert(Object.values(event.resources[key]).every(value => Number.isFinite(value)))
      if (event.event === 'gc') assert(Number.isFinite(event.gc.startTime) && Number.isFinite(event.gc.duration))
    })
    assert.equal(trace.records.at(-1).event, 'observer-exit')
  }
  assert.equal(driver.records.filter(event => event.event === 'driver-gc-error').length, 0)
  const begins = driver.records.filter(event => event.event === 'driver-write-begin')
  assert.equal(begins.length, 12)
  const expected = SCENARIOS.flatMap(scenario => [0, 1].flatMap(index => ['edit', 'restore'].map(phase => ({ scenario, index, phase }))))
  assert.deepEqual(begins.map(({ scenario, index, phase }) => ({ scenario, index, phase })), expected)
  assert.equal(run.run.samples.length, 12)
  assert.deepEqual(run.run.samples.map(sample => sample.id), expected.map(({ scenario, index, phase }) => `hmr:${run.input}:${scenario}:${index ? 'repeat' : 'first'}:${phase}`))
  for (const name of ['driver-output-visible', 'driver-profile-begin', 'driver-profile-end', 'driver-gc-begin', 'driver-gc-end', 'driver-capture-begin', 'driver-capture-end']) assert.equal(driver.records.filter(event => event.event === name).length, 12)
  const one = (name, begin) => {
    const events = driver.records.filter(event => event.event === name && samePhase(event, begin))
    assert.equal(events.length, 1, `Expected one ${name}: ${begin.scenario}/${begin.index}/${begin.phase}`)
    return events[0]
  }
  const rows = []
  for (const begin of begins) {
    const visible = one('driver-output-visible', begin)
    const profileBegin = one('driver-profile-begin', begin)
    const profileEnd = one('driver-profile-end', begin)
    const gcBegin = one('driver-gc-begin', begin)
    const gcEnd = one('driver-gc-end', begin)
    const captureBegin = one('driver-capture-begin', begin)
    const captureEnd = one('driver-capture-end', begin)
    const stages = [begin, visible, profileBegin, profileEnd, gcBegin, gcEnd, captureBegin, captureEnd]
    assert(stages.every((event, i) => !i || event.sequence > stages[i - 1].sequence))
    const pollEvents = driver.records.filter(event => event.event.startsWith('output-poll-') && samePhase(event, begin))
    assert(pollEvents.length >= 2 && pollEvents.length % 2 === 0)
    const polls = []
    for (let i = 0; i < pollEvents.length; i += 2) {
      const start = pollEvents[i], end = pollEvents[i + 1]
      assert.equal(start.event, 'output-poll-begin')
      assert.equal(end.event, 'output-poll-end')
      assert.equal(start.poll, i / 2 + 1)
      assert.equal(end.poll, start.poll)
      assert(start.sequence > begin.sequence && end.sequence < visible.sequence)
      assert(['read', 'error'].includes(end.outcome))
      assert.equal(end.matched, end.outcome === 'error' ? null : i === pollEvents.length - 2)
      polls.push({ poll: start.poll, outcome: end.outcome, matched: end.matched, contentLength: end.contentLength, ...interval(driver, start, end) })
    }
    assert.equal(polls.at(-1).outcome, 'read')
    assert.equal(polls.at(-1).matched, true)
    assert.equal(visible.wallMs, run.run.samples[rows.length].wallMs)
    const window = interval(driver, begin, visible)
    const row = {
      pair: run.pair, variant: run.variant, scenario: begin.scenario, cycle: begin.index, phase: begin.phase,
      wallMs: visible.wallMs, window, profileWait: interval(driver, profileBegin, profileEnd),
      forcedGcRequest: interval(driver, gcBegin, gcEnd), capture: interval(driver, captureBegin, captureEnd), polls,
      driverGcDuringWindow: overlappingGc(driver, window.beginEpochMs, window.endEpochMs),
      cliGcDuringWindow: overlappingGc(cli, window.beginEpochMs, window.endEpochMs),
    }
    if (begin.phase === 'restore') {
      const edit = { ...begin, phase: 'edit' }
      const editVisible = one('driver-output-visible', edit)
      row.editVisibleToRestoreWrite = interval(driver, editVisible, begin)
      row.driverGcBeforeRestore = overlappingGc(driver, epoch(driver, editVisible), epoch(driver, begin))
      row.cliGcBeforeRestore = overlappingGc(cli, epoch(driver, editVisible), epoch(driver, begin))
    }
    rows.push(row)
  }
  assert.equal(rows.reduce((sum, row) => sum + row.polls.length * 2, 0), driver.records.filter(event => event.event.startsWith('output-poll-')).length, 'Unassociated output poll')
  return rows
}

export async function analyzeDriver(reportFile, destination) {
  const reportBytes = await readFile(reportFile)
  const report = JSON.parse(reportBytes)
  assert.equal(report.contract, 'hmr-native-restore-diagnostic-v2')
  assert.equal(report.sourceScope, SOURCE_SCOPE)
  assert.equal(report.error, null)
  assert.equal(report.runs.length, 8)
  assert.equal(report.runs.reduce((sum, run) => sum + run.run.samples.length, 0), 96)
  assert(report.identityBefore.verified && report.identityAfter.verified)
  const rows = []
  for (const run of report.runs) {
    const filename = path.join(report.output, 'primary/hmr', run.input, String(run.pair), run.variant, 'watch-observer.jsonl')
    const bytes = await readFile(filename)
    assert.equal(createHash('sha256').update(bytes).digest('hex'), run.traceSha256)
    assert.deepEqual(bytes.toString().trim().split('\n').map(line => JSON.parse(line)), run.trace)
    rows.push(...analyzeRun(run))
  }
  const result = {
    contract: 'hmr-native-restore-driver-analysis-v2', diagnosticOnly: true, sourceScope: SOURCE_SCOPE,
    reportFile, reportSha256: createHash('sha256').update(reportBytes).digest('hex'), rows,
    limits: [
      'All 96 driver windows retained; callback/read attribution covers only 32 native-page-script windows in the companion analysis.',
      'Resource snapshots add synchronous observation overhead. ELU is main-thread active/idle time; CPU is cumulative process time across threads, not an additive wall phase.',
      'GC occurrence uses entry.startTime/duration. Memory and CPU snapshots describe observer delivery, not the beginning or end of GC.',
      'Output polls include reachable-script reads, cached import discovery or Babel parsing, predicates and observation; they are not single disk read timings.',
      'Capture intervals also include sample creation, input hashing, output snapshots and comparison; they are not pure artifact I/O.',
      'Exit drains delivered and queued PerformanceObserver entries only; no extra tick waits, signal handlers or timers are installed.',
      'No stable performance or polling-only causal conclusion follows from these diagnostic windows.',
    ],
  }
  await writeFile(destination, `${JSON.stringify(result, null, 2)}\n`, { flag: 'wx' })
  return { rows: rows.length, reportSha256: result.reportSha256, destination }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  assert.equal(process.argv.length, 4, 'Usage: node analyzeDriver.mjs <report.json> <new-analysis.json>')
  console.log(JSON.stringify(await analyzeDriver(process.argv[2], process.argv[3]), null, 2))
}
